(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.Loyalty=factory();})(typeof globalThis!=='undefined'?globalThis:this,function(){
  'use strict';
  function program(card){return {type:'visits',pointsPerVisit:10,pointsCost:100,discountType:'percent',discountValue:20,barcodeFormat:'qr',...(card.program||{})};}
  function validate(card){const p=program(card);if(!['visits','discount','points'].includes(p.type))throw Error('اختر نظام ولاء صحيحًا.');if(!['qr','code128'].includes(p.barcodeFormat))throw Error('نوع الرمز غير صحيح.');if(!Number.isInteger(card.target)||card.target<2||card.target>12)throw Error('عدد الزيارات بين ٢ و١٢.');if(!Number.isInteger(p.pointsPerVisit)||p.pointsPerVisit<1||p.pointsPerVisit>10000||!Number.isInteger(p.pointsCost)||p.pointsCost<1||p.pointsCost>1000000)throw Error('قواعد النقاط غير صحيحة.');if(!['percent','amount'].includes(p.discountType)||!Number.isFinite(p.discountValue)||p.discountValue<=0||p.discountValue>(p.discountType==='percent'?100:100000))throw Error('قيمة الخصم غير صحيحة.');return p;}
  function label(card){const p=program(card);return p.type==='discount'?`خصم ${p.discountValue}${p.discountType==='percent'?'٪':' ريال'}`:card.rewardChoices?.length?'اختيار مكافأة':card.reward;}
  function ruleKey(card){const p=program(card);return JSON.stringify({type:p.type,target:card.target,pointsPerVisit:p.pointsPerVisit,pointsCost:p.pointsCost,discountType:p.discountType,discountValue:p.discountValue});}
  function rewardSnapshot(card){const p=program(card);return {type:p.type,label:label(card),discountType:p.type==='discount'?p.discountType:null,discountValue:p.type==='discount'?p.discountValue:null,earnedAt:Date.now(),...(p.type!=='discount'&&card.rewardChoices?.length?{choices:structuredClone(card.rewardChoices)}:{})};}
  function prepare(member,card){member.points=Number.isSafeInteger(member.points)?member.points:0;member.stamps=Number.isSafeInteger(member.stamps)?member.stamps:0;member.visits=Number.isSafeInteger(member.visits)?member.visits:0;member.rewardItems??=Array.from({length:member.rewards||0},()=>rewardSnapshot({...card,rewardChoices:[]}));member.rewards=member.rewardItems.length;return member;}
  function available(member,card){const p=program(card);return (member.rewardItems?.length??member.rewards??0)+(p.type==='points'?Math.floor((member.points||0)/p.pointsCost):0);}
  function protectedBalance(m){return (m.stamps||0)>0||(m.points||0)>0||(m.rewards||0)>0||(m.rewardItems?.length||0)>0;}
  function snapshot(m,card){prepare(m,card);return structuredClone({stamps:m.stamps,points:m.points,visits:m.visits,rewards:m.rewards,rewardItems:m.rewardItems,rewardChoiceId:m.rewardChoiceId||''});}
  function nextChoices(m,card){if((m.rewardItems?.length??m.rewards??0)>0)return m.rewardItems?.[0]?.choices||[];return program(card).type==='points'&&(m.points||0)>=program(card).pointsCost?card.rewardChoices||[]:[];}
  function apply(m,card,action,options={}){const p=validate(card);prepare(m,card);const before=snapshot(m,card);let earned=false,reward=null;if(action==='stamp'){m.visits++;if(p.type==='points'){const was=available(m,card);m.points+=p.pointsPerVisit;earned=available(m,card)>was;}else{m.stamps++;if(m.stamps>=card.target){m.stamps-=card.target;m.rewardItems.push(rewardSnapshot(card));earned=true;}}}else if(action==='redeem'){const choices=nextChoices(m,card),id=options.choiceId||m.rewardChoiceId||'',choice=choices.find(x=>x.id===id);if(options.choiceId&&!choice)throw Error('المكافأة المختارة غير متاحة.');if(choices.length&&!choice)throw Error('اختر المكافأة قبل صرفها.');if(m.rewardItems.length)reward=m.rewardItems.shift();else if(p.type==='points'&&m.points>=p.pointsCost){m.points-=p.pointsCost;reward=rewardSnapshot(card);}else throw Error('لا توجد مكافأة جاهزة لهذا العميل.');if(choice)reward={...reward,label:choice.label,choiceId:choice.id};delete m.rewardChoiceId;}else throw Error('عملية غير صحيحة.');m.rewards=m.rewardItems.length;return {before,earned,reward,stamps:m.stamps,points:m.points,available:available(m,card)};}
  return {program,validate,label,ruleKey,rewardSnapshot,prepare,available,protectedBalance,snapshot,nextChoices,apply};
});
